-- Fixed, bounded review approval. No credential reads and no Pin dispatch.
begin;
set local statement_timeout='20s';
set local lock_timeout='5s';
select pg_advisory_xact_lock(1617125,13);
create temporary table reviewed_input as select * from jsonb_to_recordset('[{"queue_id": "1bc4aa5b-e7a9-4c86-95cb-5703de22be35", "shop": "LoomGoStudio", "listing_id": "4356345034", "source_url": "https://www.etsy.com/listing/4356345034/embroidered-mulberry-silk-organza-fabric", "category": "Silk & Organza Fabric", "image_url": null, "destination_url": "https://www.etsy.com/listing/4356345034/embroidered-mulberry-silk-organza-fabric", "title": "Embroidered Mulberry Silk Organza Fabric: Chinese Pavilion Landscape", "body": "Embroidered Mulberry Silk Organza Fabric: Chinese Pavilion Landscape Style: chinese, landscape, embroidered. Materials: silk. View details and available options on Etsy.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Embroidered Mulberry Silk Organza Fabric: Chinese Pavilion Landscape", "new_body": "Embroidered Mulberry Silk Organza Fabric: Chinese Pavilion Landscape. Fabric for sewing projects from LoomGoStudio. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/58959935/r/il/5a5bc5/7178348031/il_794xN.7178348031_ruoa.jpg", "checked_at": "2026-10-13T02:55:06.806Z"}, {"queue_id": "c8c132db-29ab-4477-9ca3-5e809041fad2", "shop": "LoomGoStudio", "listing_id": "4364578832", "source_url": "https://www.etsy.com/listing/4364578832/beige-floral-embroidered-organza-fabric", "category": "Silk & Organza Fabric", "image_url": null, "destination_url": "https://www.etsy.com/listing/4364578832/beige-floral-embroidered-organza-fabric", "title": "Beige Floral Embroidered Organza Fabric, Sheer Tulle Mesh", "body": "Beige Floral Embroidered Organza Fabric, Sheer Tulle Mesh Style: floral, embroidered, bridal. Materials: organza. View details and available options on Etsy.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": null, "new_title": "Beige Floral Embroidered Organza Fabric, Sheer Tulle Mesh", "new_body": "Beige Floral Embroidered Organza Fabric, Sheer Tulle Mesh. Fabric for sewing projects from LoomGoStudio. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/58959935/r/il/319e38/7174563188/il_794xN.7174563188_3yh4.jpg", "checked_at": "2026-10-13T03:01:20.654Z"}, {"queue_id": "f929d511-3910-4794-bd4e-bf084c1887e2", "shop": "LoomGoStudio", "listing_id": "4366040480", "source_url": "https://www.etsy.com/listing/4366040480/mulberry-silk-organza-fabric-chinese", "category": "Silk & Organza Fabric", "image_url": null, "destination_url": "https://www.etsy.com/listing/4366040480/mulberry-silk-organza-fabric-chinese", "title": "Mulberry Silk Organza Fabric: Chinese Pavilion Embroidery, Sheer Hanfu Material", "body": "Mulberry Silk Organza Fabric: Chinese Pavilion Embroidery, Sheer Hanfu Material Style: chinese, landscape, embroidered, hanfu. Materials: silk. View details and available options on Etsy.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Mulberry Silk Organza Fabric: Chinese Pavilion Embroidery, Sheer Hanfu Material", "new_body": "Mulberry Silk Organza Fabric: Chinese Pavilion Embroidery, Sheer Hanfu Material. Fabric for sewing projects from LoomGoStudio. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/58959935/r/il/209e08/7230087161/il_794xN.7230087161_k9b0.jpg", "checked_at": "2026-10-13T03:01:22.416Z"}, {"queue_id": "834d0041-e724-4de7-b3b5-1f4669009dd2", "shop": "LoomGoStudio", "listing_id": "4416533490", "source_url": "https://www.etsy.com/listing/4416533490/pink-jacquard-fabric-embossed-texture", "category": "Jacquard Fabric", "image_url": null, "destination_url": "https://www.etsy.com/listing/4416533490/pink-jacquard-fabric-embossed-texture", "title": "Pink Jacquard Fabric, Embossed Texture Textile, Vintage Cheongsam Coat Fabric", "body": "Pink Jacquard Fabric, Embossed Texture Textile, Vintage Cheongsam Coat Fabric Style: chinese, cheongsam, vintage, embossed. Materials: polyester. View details and available options on Etsy.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": null, "new_title": "Pink Jacquard Fabric, Embossed Texture Textile, Vintage Cheongsam Coat Fabric", "new_body": "Pink Jacquard Fabric, Embossed Texture Textile, Vintage Cheongsam Coat Fabric. Fabric for sewing projects from LoomGoStudio. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/58959935/r/il/7d76f1/7513903217/il_794xN.7513903217_6i9z.jpg", "checked_at": "2026-10-13T03:02:07.567Z"}, {"queue_id": "8ef3d55a-0110-489b-9213-e9635771154e", "shop": "LoomGoStudio", "listing_id": "4442572721", "source_url": "https://www.etsy.com/listing/4442572721/chinese-silk-embroidered-fabric-for-home", "category": "Jacquard Fabric", "image_url": null, "destination_url": "https://www.etsy.com/listing/4442572721/chinese-silk-embroidered-fabric-for-home", "title": "Chinese Silk Brocade Fabric, Landscape Embroidery, Sewing Material", "body": "Chinese Silk Brocade Fabric, Landscape Embroidery, Sewing Material Style: chinese, landscape, embroidered, brocade. Materials: silk, rayon. View details and available options on Etsy.", "handle": "mydecorshop", "mapped": true, "history_count": 0, "review_exists": false, "board_id": "499618221101238533", "new_title": "Chinese Silk Brocade Fabric, Landscape Embroidery, Sewing Material", "new_body": "Chinese Silk Brocade Fabric, Landscape Embroidery, Sewing Material. Fabric for sewing projects from LoomGoStudio. View the original Etsy listing for options and current details.", "new_image_url": "https://i.etsystatic.com/58959935/r/il/4ba404/7659212389/il_794xN.7659212389_fk16.jpg", "checked_at": "2026-10-13T03:02:08.838Z"}]'::jsonb) as x(queue_id uuid,shop text,listing_id text,source_url text,category text,image_url text,destination_url text,title text,body text,handle text,board_id text,new_title text,new_body text,checked_at timestamptz,new_image_url text);
select q.id from publish_queue q join reviewed_input x on x.queue_id=q.id for update of q;
select cv.id from content_variants cv join publish_queue q on q.content_variant_id=cv.id join reviewed_input x on x.queue_id=q.id for update of cv;
select p.id from products p join publish_queue q on q.product_id=p.id join reviewed_input x on x.queue_id=q.id for update of p;
do $$
begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard settings required'; end if;
 if exists(select 1 from reviewed_input where checked_at < now()-interval '24 hours' or checked_at>now()) then raise exception 'Fixed approval expired'; end if;
 if (select count(*) from reviewed_input x join publish_queue q on q.id=x.queue_id join products p on p.id=q.product_id and p.shop_id=q.shop_id join shops s on s.id=q.shop_id join content_variants cv on cv.id=q.content_variant_id and cv.product_id=p.id and cv.shop_id=s.id join social_accounts a on a.id=q.social_account_id
 where q.platform='pinterest' and cv.platform='pinterest' and q.status in ('draft','ready') and cv.status in ('draft','ready') and s.status='active' and a.active and a.handle=x.handle and a.platform='pinterest' and s.shop_name=x.shop and p.etsy_listing_id=x.listing_id and p.etsy_url=x.source_url and cv.destination_url=x.destination_url and cv.board_or_category=x.category and cv.image_url is not distinct from x.image_url and cv.title=x.title and cv.body=x.body
 and exists(select 1 from shop_social_accounts m where m.shop_id=s.id and m.social_account_id=a.id and m.platform='pinterest' and m.active)
 and exists(select 1 from pinterest_oauth_credentials cr where cr.social_account_id=a.id and lower(cr.pinterest_username)=lower(a.handle))
 and not exists(select 1 from publish_history h where h.product_id=p.id and h.platform='pinterest')
 and not exists(select 1 from pinterest_publish_attempts pa where pa.queue_id=q.id)) <> 5 then raise exception 'Expected 5 unchanged, mapped, unattempted drafts'; end if;
 if exists(select 1 from pinterest_publish_reviews rev join reviewed_input x on rev.queue_id=x.queue_id where rev.board_id<>x.board_id or rev.snapshot<>pinterest_publish_snapshot(x.queue_id)) then raise exception 'Existing review differs'; end if;
end $$;
update products p set listing_status='active',last_seen_at=x.checked_at from publish_queue q join reviewed_input x on x.queue_id=q.id where p.id=q.product_id;
update content_variants cv set status=case when x.board_id is null then 'draft'::content_status else 'ready'::content_status end,title=x.new_title,body=x.new_body,image_url=x.new_image_url from publish_queue q join reviewed_input x on x.queue_id=q.id where cv.id=q.content_variant_id;
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select x.queue_id,x.board_id,pinterest_publish_snapshot(x.queue_id),x.checked_at,x.source_url from reviewed_input x where x.board_id is not null on conflict(queue_id) do nothing;
update publish_queue q set status='ready',updated_at=now() from reviewed_input x where q.id=x.queue_id and q.status='draft' and x.board_id is not null;
select json_build_object('queue_id',q.id,'status',q.status,'board_id',rev.board_id,'snapshot_matches',rev.snapshot=pinterest_publish_snapshot(q.id),'listing_checked_at',rev.listing_checked_at) from publish_queue q join reviewed_input x on x.queue_id=q.id left join pinterest_publish_reviews rev on rev.queue_id=q.id;
select json_build_object('public_publish_enabled',enabled) from pinterest_publish_settings where singleton;
commit;
